package com.example.starter.domain;

import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * 依赖锁定解析器：在一致性仓库快照上求解精确版本组合。
 *
 * <p>解析分两阶段：
 * <ol>
 *   <li><b>必选阶段</b>：根版本固定；仅考虑必选依赖与支持目标平台（或 ANY）的候选，
 *       其余名称按字典序选择下一个尚未解析的依赖，候选版本从高到低尝试，遇冲突回退，
 *       取首个完整可行结果。必选阶段绝不因可选依赖降级或失败。</li>
 *   <li><b>可选阶段</b>：必选集合确定后，按“来源名称、依赖名称”字典序遍历当前已选
 *       制品的可选依赖；已选且满足区间记为 included；未选则在不改变已选集合的前提下
 *       尝试加入其最高可行版本及必选闭包，成功后继续扫描新增制品的可选依赖，
 *       失败记为 skipped 并保存稳定原因。可选依赖不能覆盖根或更换此前选择。</li>
 * </ol>
 * 已选制品之间必须互相满足必选区间约束，因此依赖图存在环时也会被正确校验。
 */
public final class LockResolver {

    private LockResolver() {
    }

    /**
     * 兼容旧调用：不做平台过滤，返回名称 -> 精确版本（名称升序）；不可行返回 null。
     */
    public static Map<String, Integer> resolve(RepositorySnapshot snapshot,
                                               String rootName, int rootVersion) {
        ResolutionResult result = resolve(snapshot, rootName, rootVersion, null);
        return result == null ? null : result.entries();
    }

    /**
     * 按目标平台求解锁定组合（必选 + 可选两阶段）。
     *
     * @param targetPlatform 目标平台 {@code os/arch}；传 null 表示不做平台过滤（旧逻辑）
     * @return 完整解析结果；根不存在/已撤回/不支持平台或必选闭包不可行时返回 null
     */
    public static ResolutionResult resolve(RepositorySnapshot snapshot,
                                           String rootName, int rootVersion,
                                           String targetPlatform) {
        Map<String, List<ArtifactVersion>> all = snapshot.artifacts();
        List<ArtifactVersion> rootCandidates = all.get(rootName);
        if (rootCandidates == null) {
            throw new IllegalArgumentException("根制品不存在: " + rootName);
        }
        ArtifactVersion root = rootCandidates.stream()
                .filter(a -> a.version() == rootVersion && !a.withdrawn())
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException(
                        "根制品版本不存在或已撤回: " + rootName + ":" + rootVersion));
        if (targetPlatform != null && !root.supports(targetPlatform)) {
            // 平台不兼容的精确根不可参与锁定（调用方据此返回 422）。
            return null;
        }

        TreeMap<String, ArtifactVersion> chosen = new TreeMap<>();
        chosen.put(rootName, root);
        // 根可能自依赖：固定版本也必须落在自身声明的必选区间内。
        if (!satisfiesChosen(root, chosen)) {
            return null;
        }
        if (!solveMandatory(all, chosen, targetPlatform)) {
            return null;
        }

        List<OptionalDecision> decisions = resolveOptional(all, chosen, targetPlatform);

        TreeMap<String, Integer> entries = new TreeMap<>();
        chosen.forEach((name, artifact) -> entries.put(name, artifact.version()));
        return new ResolutionResult(entries, decisions);
    }

    /**
     * 可选阶段：反复取当前已选制品中字典序最小的未处理可选边处理，
     * 新增制品会引入更小的边，因此每次全局取最小值即可保持稳定遍历顺序。
     */
    private static List<OptionalDecision> resolveOptional(
            Map<String, List<ArtifactVersion>> all,
            TreeMap<String, ArtifactVersion> chosen,
            String targetPlatform) {
        List<OptionalDecision> decisions = new java.util.ArrayList<>();
        java.util.Set<String> processed = new java.util.HashSet<>();

        while (true) {
            // 找 (sourceName, dependencyName) 字典序最小的未处理可选边。
            String nextSource = null;
            DependencyRange nextDep = null;
            for (Map.Entry<String, ArtifactVersion> entry : chosen.entrySet()) {
                String sourceName = entry.getKey();
                List<DependencyRange> optionals = entry.getValue().dependencies().stream()
                        .filter(DependencyRange::optional)
                        .sorted(java.util.Comparator.comparing(DependencyRange::name))
                        .toList();
                for (DependencyRange dep : optionals) {
                    String edge = sourceName + '�' + dep.name();
                    if (processed.contains(edge)) {
                        continue;
                    }
                    if (nextDep == null
                            || sourceName.compareTo(nextSource) < 0
                            || (sourceName.equals(nextSource)
                            && dep.name().compareTo(nextDep.name()) < 0)) {
                        nextSource = sourceName;
                        nextDep = dep;
                    }
                }
            }
            if (nextDep == null) {
                break;
            }
            processed.add(nextSource + '�' + nextDep.name());
            decisions.add(processOptionalEdge(all, chosen, nextSource, nextDep, targetPlatform));
        }
        return List.copyOf(decisions);
    }

    /**
     * 处理一条可选依赖边：目标已选则只做区间判定；未选则尝试加入最高可行版本及必选闭包。
     * 任何尝试都不得更换或移除已选集合中的制品。
     */
    private static OptionalDecision processOptionalEdge(
            Map<String, List<ArtifactVersion>> all,
            TreeMap<String, ArtifactVersion> chosen,
            String sourceName, DependencyRange dep,
            String targetPlatform) {
        ArtifactVersion already = chosen.get(dep.name());
        if (already != null) {
            // 目标名称已选：可选依赖不能更换此前选择，仅判定区间是否满足。
            if (already.version() >= dep.minimumVersion()
                    && already.version() <= dep.maximumVersion()) {
                return OptionalDecision.included(sourceName, dep, already.version());
            }
            return OptionalDecision.skippedSelectedOutOfRange(sourceName, dep, already.version());
        }

        // 目标未选：候选从高到低，必须未撤回、兼容平台、落在声明区间内。
        boolean anyEligible = false;
        List<ArtifactVersion> candidates = all.getOrDefault(dep.name(), List.of());
        for (ArtifactVersion candidate : candidates) {
            if (candidate.withdrawn()
                    || candidate.version() < dep.minimumVersion()
                    || candidate.version() > dep.maximumVersion()) {
                continue;
            }
            if (targetPlatform != null && !candidate.supports(targetPlatform)) {
                continue;
            }
            anyEligible = true;

            // 在已选集合的副本上尝试；成功才整体接受，失败丢弃全部尝试产物。
            TreeMap<String, ArtifactVersion> trial = new TreeMap<>(chosen);
            trial.put(dep.name(), candidate);
            if (!satisfiesChosen(candidate, trial)) {
                continue;
            }
            if (solveMandatory(all, trial, targetPlatform)) {
                // 接受候选及其必选闭包；其可选依赖交由外层循环继续扫描。
                chosen.clear();
                chosen.putAll(trial);
                return OptionalDecision.included(sourceName, dep, candidate.version());
            }
        }
        return anyEligible
                ? OptionalDecision.skippedInfeasibleClosure(sourceName, dep)
                : OptionalDecision.skippedNoCandidate(sourceName, dep);
    }

    /**
     * 递归回溯：选出字典序最小的未解析必选依赖名称，从高到低尝试候选版本。
     * 仅追踪必选依赖；进入时已在 chosen 中的名称视为固定，不会被替换。
     */
    private static boolean solveMandatory(Map<String, List<ArtifactVersion>> all,
                                          TreeMap<String, ArtifactVersion> chosen,
                                          String targetPlatform) {
        // 汇总所有已选制品对“尚未解析名称”的必选区间约束，取交集。
        String next = null;
        int lo = Integer.MAX_VALUE;
        int hi = Integer.MIN_VALUE;
        for (ArtifactVersion artifact : chosen.values()) {
            for (DependencyRange dep : artifact.dependencies()) {
                if (dep.optional() || chosen.containsKey(dep.name())) {
                    continue;
                }
                if (next == null || dep.name().compareTo(next) < 0) {
                    next = dep.name();
                    lo = dep.minimumVersion();
                    hi = dep.maximumVersion();
                } else if (dep.name().equals(next)) {
                    lo = Math.max(lo, dep.minimumVersion());
                    hi = Math.min(hi, dep.maximumVersion());
                }
            }
        }

        if (next == null) {
            // 所有必选依赖均已解析为精确版本。
            return true;
        }
        if (lo > hi) {
            // 多个已选制品对该名称的必选区间交集为空。
            return false;
        }

        // 候选从高到低（快照已按版本号降序），跳过撤回、平台不兼容和区间外版本。
        List<ArtifactVersion> candidatesList = all.getOrDefault(next, List.of());
        for (ArtifactVersion candidate : candidatesList) {
            if (candidate.withdrawn() || candidate.version() < lo || candidate.version() > hi) {
                continue;
            }
            if (targetPlatform != null && !candidate.supports(targetPlatform)) {
                continue;
            }
            // 新候选对所有已选名称（含自身）的必选区间必须成立；环依赖在此被校验。
            if (!satisfiesChosen(candidate, chosen)) {
                continue;
            }
            chosen.put(next, candidate);
            if (solveMandatory(all, chosen, targetPlatform)) {
                return true;
            }
            chosen.remove(next);
        }
        return false;
    }

    /**
     * 校验候选制品声明的、指向已选名称的必选依赖区间均被已选精确版本满足。
     */
    private static boolean satisfiesChosen(ArtifactVersion candidate,
                                           Map<String, ArtifactVersion> chosen) {
        for (DependencyRange dep : candidate.dependencies()) {
            if (dep.optional()) {
                continue;
            }
            ArtifactVersion selected = chosen.get(dep.name());
            if (selected == null) {
                continue;
            }
            if (selected.version() < dep.minimumVersion() || selected.version() > dep.maximumVersion()) {
                return false;
            }
        }
        return true;
    }
}

